input.command:
$ErrorActionPreference='Continue'
foreach ($r in "$HOME\.claude","$HOME\.claude\skills","$HOME\.claude\global-memory") {
  "=== $r"
  $s = git -C $r status --porcelain
  if ($s) { "dirty: $(@($s).Count)"; git -C $r add -A; git -C $r commit -q -m "windows snapshot before sync" }
  $before = git -C $r rev-parse HEAD
  git -C $r pull --no-edit 2>&1 | Select-Object -Last 3
  $n = git -C $r rev-list --count "$before..HEAD"
  "new commits: $n"; if ($n -gt 0) { git -C $r log -1 --format='%h %s' }
  git -C $r push 2>&1 | Select-Object -Last 1
}
Test-Path "$HOME\.claude\machine.md"

