input.command:
git -C $HOME\.claude status --porcelain | Measure-Object | % Count
$skip='.claude','_tools','_DRIVE','token-dashboard'
$root='C:\Users\eric_rash\Desktop\DEV'
$dirs = @(Get-ChildItem $root -Directory) + @(Get-ChildItem "$root\Football" -Directory -EA 0) + @(Get-ChildItem "$root\SpecialRequests" -Directory -EA 0)
$out=@()
foreach ($d in $dirs) {
  if ($skip -contains $d.Name -or $d.Name -like '*_OLD_merged*' -or $d.Name -in 'Football','SpecialRequests' -and -not (Test-Path "$($d.FullName)\.git")) { continue }
  if ($d.Attributes -band [IO.FileAttributes]::ReparsePoint) { continue }
  if (-not (Test-Path "$($d.FullName)\.git")) { $out += "NOREPO $($d.FullName)"; continue }
  $rem = git -C $d.FullName remote get-url origin 2>$null
  if (-not $rem) { $out += "NOREMOTE $($d.FullName)"; continue }
  if ($rem -notmatch 'erash11') { $out += "OTHERREMOTE $($d.FullName) $rem"; continue }
  $u = @(git -C $d.FullName status --porcelain 2>$null).Count
  $p = git -C $d.FullName rev-list --count '@{u}..HEAD' 2>$null
  if ($u -gt 0 -or ($p -and [int]$p -gt 0)) { $out += "DIRTY $($d.Name) u=$u p=$p" }
  $out += "OK $($d.FullName)"
}
$out | ? { $_ -notlike 'OK *' }
"repos ok/total: " + ($out | ? { $_ -like 'OK *' }).Count
$local = $out | ? { $_ -like 'OK *' } | % { Split-Path ($_.Substring(3)) -Leaf }
$gh = (gh repo list erash11 --limit 300 --json name | ConvertFrom-Json).name
$ex='dotclaude','SecondBrain','claude-skills','claude-memory-compiler','DEV','DexaProject','claude-global-memory'
"missing locally: " + (($gh | ? { $_ -notin $local -and $_ -notin $ex }) -join ', ')

