input.command:
$root='C:\Users\eric_rash\Desktop\DEV'
$names='CommandCentre','PythonScripts_2024','skill-audit-2026-09-05','Life-OS','Gemini_Projects','VALD_analytics','SoftwareTech_Mgmt_Framework','AI_Analyst','ValdReport','Sport_Tech_Vetting','FootballWeightTargetTool','BodWeightWeb','Risk_Exposure_Windows','OKRs_2026-27','2026-3-18_BodyWeightNorms','CPSS_BaylorSportScience_Curriculum','_obsidian_extracted_from_FaceComps','KnowledgeManagement','2025-11-25_EOS_Football_Analysis_GPS_ERR','B_Ellis','morning-briefing','SoftwareTechDocs','SprintLab','InjurPred','BodyWeightWebApp','Jump_Dash','GameONPaper','Non-Negative-Matrix-Factorization-RTP','PostGameReport','JumpReporting','PT_Dash','speed-velocity-profiling','cmj-norms-app','shiny-vertical-jump','PostSesaonAnalysis','vision-builder','Education_Content_Agent','CoachReport_Prototypes','Football_Data_DEV','WeeklyCoachReport','AgentAssist'
$found = Get-ChildItem $root -Directory -Recurse -Depth 3 -EA 0 | ? { $_.Name -in $names -and $_.FullName -notmatch '\\_DRIVE\\' }
$found | % { $_.FullName.Replace($root,'') }
"not found: " + (($names | ? { $_ -notin $found.Name }) -join ', ')
Get-Content "$root\_ARCHIVE\README.md" -TotalCount 25 -EA 0

$root='C:\Users\eric_rash\Desktop\DEV'
foreach($r in 'CATES','Performance_Playbook'){ Add-Content "$root\$r\.gitignore" "`n.claude/worktrees/"; git -C $root\$r add .gitignore; git -C $root\$r commit -q -m "windows snapshot before sync: ignore .claude/worktrees" }
$skip='.claude','_tools','_DRIVE','token-dashboard'
$dirs = @(Get-ChildItem $root -Directory) + @(Get-ChildItem "$root\Football" -Directory -EA 0) + @(Get-ChildItem "$root\SpecialRequests" -Directory -EA 0)
$log=@()
foreach ($d in $dirs) {
  if ($skip -contains $d.Name -or $d.Name -like '*_OLD_merged*' -or -not (Test-Path "$($d.FullName)\.git")) { continue }
  $p=$d.FullName; $rem = git -C $p remote get-url origin 2>$null; if ($rem -notmatch 'erash11') { continue }
  $br = git -C $p branch --show-current
  $before = git -C $p rev-parse HEAD
  git -C $p fetch -q origin 2>&1 | Out-Null
  $m = git -C $p merge --no-edit "origin/$br" 2>&1
  if (Test-Path "$p\.git\MERGE_HEAD") { $log += "CONFLICT $p :: $($m -join ' | ')"; continue }
  if ($LASTEXITCODE -ne 0) { $log += "MERGEFAIL $p :: $($m | Select-Object -Last 2)"; continue }
  $n = git -C $p rev-list --count "$before..HEAD"
  if ([int]$n -gt 0) { $log += "PULLED $($d.Name) +$n" }
  $ahead = git -C $p rev-list --count "origin/$br..HEAD" 2>$null
  if ($ahead -and [int]$ahead -gt 0) { $o = git -C $p push 2>&1; if ($LASTEXITCODE -ne 0) { $log += "PUSHFAIL $($d.Name) $($o|Select-Object -Last 1)" } else { $log += "PUSHED $($d.Name) $ahead" } }
}
$log

