{
  "topic": "NCAA SSI open decisions",
  "doc": "docs/ssi-open-decisions-design.md",
  "project": "C:\\Users\\eric_rash\\Desktop\\DEV\\NCAA_BestPractices_Doc",
  "created": "2026-10-05T13:18:16Z",
  "agent": { "status": "waiting", "since": "2026-10-05T13:20:00Z", "handled": 0 },
  "note": "Most of these are Chris's to decide. For those, you are settling what you walk in recommending. The DEXA and repo questions are yours to decide outright. Round 1: three independent questions.",
  "terms": [
    { "term": "the guide", "def": "The SSI best-practices document in deliverables/ (draft v1, 10 pages, sections 0–7, Forms A–E).", "avoid": ["policy (unless decision 1 makes it one)", "the doc"] },
    { "term": "the framework", "def": "The Software & Technology Management Framework (draft 08-14, archived repo), which owns the request-and-review process (SSI Rec 4).", "avoid": ["SoftwareTech doc", "tech framework"] },
    { "term": "physiologic data", "def": "Body and health-adjacent measures (HR, HRV, DEXA, sleep, biomarkers), as distinct from performance data (GPS distance, jump height, velocity).", "avoid": ["medical data", "health data (when performance data is meant)"] }
  ],
  "questions": [
    {
      "id": "q1", "round": 1, "deps": [],
      "title": "Decision 1 for Chris: a best-practice guide, or a formal department policy?",
      "body": "This sets the document's form and who has to sign it. Draft v1 is written as a guide plus procedures and forms. If Chris wants a formal policy, sections 0–2 get rewritten, the signer question becomes harder (a policy needs an owner with authority, which at UT is the Chief Medical Officer), and OGC review moves earlier. At the 7/30 meeting, leadership said it preferred flexible best-practice documents to rigid formal policy.",
      "options": [
        { "k": "A", "text": "Guide plus procedures and forms (as drafted)" },
        { "k": "B", "text": "Guide plus forms, with a one-page policy statement on top that gives it teeth" },
        { "k": "C", "text": "Formal department policy, like UT's SMED-8055" }
      ],
      "rec": { "option": "B", "why": "Go in with B. It keeps everything in draft v1 and matches what leadership said on 7/30, and the one-page statement answers the obvious pushback that a guide has no force. That page would say the guide is required practice, name who owns it, and set the review cycle. A alone risks a guide nobody has to follow. C costs a rewrite of sections 0–2 and pulls OGC onto the critical path before 11/06. The trade-off: B needs a named signer for that one page, which Q4 settles next." },
      "status": "open", "durable": true, "updated": false, "thread": []
    },
    {
      "id": "q2", "round": 1, "deps": [],
      "title": "Data ownership: what position do you bring to Chris?",
      "body": "Two Baylor drafts disagree. The March draft says the institution owns the data and athletes get access. The framework spec says the athlete owns physiologic data. This drives guide §4.1, the consent form (Form A), and the vendor addendum's ownership clause (Form B). OGC has the final say, but Chris needs a working position to send them.",
      "options": [
        { "k": "A", "text": "Institution owns all of it; athletes get access and copies (March draft)" },
        { "k": "B", "text": "Split: the athlete owns physiologic data; the institution owns performance data, with athlete access" },
        { "k": "C", "text": "The athlete owns all of it; the institution has a licence to use it" }
      ],
      "rec": { "option": "B", "why": "The split follows the line SSI and the webinar draw: venue tracking is unavoidable, but body data needs consent. It also matches the framework, which this guide is meant to supply content for, so the two documents don't contradict each other. The cost is that every platform's data has to be labelled physiologic or performance, and some cases are fuzzy (is HR from a GPS vest physiologic?). OGC may push back towards A for HIPAA/FERPA reasons. If they do, B degrades cleanly to A plus stronger access rights, so it is the safer opening position." },
      "status": "open", "durable": true, "updated": false, "thread": []
    },
    {
      "id": "q3", "round": 1, "deps": [],
      "title": "Yours to decide: where does DEXA data live?",
      "body": "DexaProject (identifiable body-composition data) sits on Google Drive under a non-Baylor account. Guide §4.2 says restricted, Baylor-controlled storage is the rule, and the guide's DEXA row now reads 'unverified'. Chris will read a guide that the author's own project doesn't follow. The Nov 6 first draft is the deadline to resolve it either way.",
      "options": [
        { "k": "A", "text": "Move it to Baylor storage (Box, via Box Drive) before 11/06; the guide stays as written" },
        { "k": "B", "text": "Keep it on personal Drive and soften §4.2 to allow approved exceptions" },
        { "k": "C", "text": "Ask ITS where it should live and decide after their answer" }
      ],
      "rec": { "option": "A", "why": "The guide's credibility depends on Applied Performance following it first, and DEXA is the clearest example of physiologic data in the whole program. Box Drive already works on this laptop (Baylor blocks the Box connector, but the local folder is fine). The cost is breaking the Mac's direct access path and the scripts that point at the Drive path, which means re-pointing DexaProject on both machines. B makes the guide weaker to fit one project. C waits on ITS, who haven't replied since mid-August." },
      "status": "open", "durable": true, "updated": false, "thread": []
    }
  ]
}

