s["questions"] += [
    {
        "id": "q7", "round": 3, "deps": ["q4"],
        "title": "If no one is held to it, what does 'in use by 12/16' mean?",
        "body": "The charter's done-means is 'Chris signs it off, and it is in use by 2026-12-16' (step 4: working group chartered or scheduled, consent form live for spring, Chris confirms). A guide with no enforcement is only 'in use' where its pieces are wired into something people already do. Otherwise step 4 is a judgement call Chris makes on a vibe, and the project closes on paper only.",
        "options": [
            {"k": "A", "text": "In use = the consent form (Form A) is in spring onboarding and the offboarding checklist (Form E) is in the HR/ITS departure steps"},
            {"k": "B", "text": "In use = Chris signs off and the guide is posted where staff can find it; nothing more"},
            {"k": "C", "text": "In use = the next new technology request runs through the framework using the guide's scoring and vendor checklist"}
        ],
        "rec": {"option": "A", "why": "Two forms placed in two existing processes is a test you can check on 12/16 without anyone being 'held to' anything: athletes see the consent form because onboarding hands it to them, and departures trigger the checklist because HR already runs one. B is honest about the guideline status but makes the charter's step 4 meaningless and the project easy to call done with zero effect. C depends on a request happening before 12/16, which you don't control. Cost of A: it needs Compliance (onboarding) and HR/ITS (departures) to accept the forms, which adds two asks to the 10/15–10/24 input window."},
        "status": "open", "durable": True, "updated": False, "thread": []
    },
    {
        "id": "q8", "round": 3, "deps": ["q6"],
        "title": "Working group and education: build new, or ride existing?",
        "body": "SSI Rec 1.1 calls for a standing multidisciplinary working group with student-athlete members; Rec 2 needs annual education by group. Q6 = A keeps education short. Draft v1 assumes a new working group (quorum four seats including Athletic Medicine, ten-day email vote) and education delivered at existing Compliance and orientation sessions. Chris has to say whether any of this already exists.",
        "options": [
            {"k": "A", "text": "Ask Chris to charter a small new working group (with a SAAC seat); education rides on Compliance/orientation sessions"},
            {"k": "B", "text": "No new group: an existing staff meeting takes the role, with a SAAC rep invited when technology is on the agenda; education rides on existing sessions"},
            {"k": "C", "text": "Defer both to the first annual review; the guide names them as goals"}
        ],
        "rec": {"option": "B", "why": "Given your Q4 answer (guidelines, nobody held to them), a new standing body is the part most likely to never meet. Using a meeting that already happens, with a student-athlete invited when technology is discussed, meets the spirit of Rec 1.1 at almost no cost and can be 'in use' by 12/16. A is the SSI-literal version and reads better to the NCAA, but it needs members, a charter and a calendar. C is honest but leaves the governance section empty. Cost of B: the guide's quorum and email-vote rules (from the R3 review) get simplified, and §1 needs a rewrite of about a paragraph."},
        "status": "open", "durable": True, "updated": False, "thread": []
    }
]

s["note"] = "Round 3: Q1 is reopened, because your Q4 answer (guidelines only) undoes the reason for B. Two new questions follow from it. Contacts in OGC/Procurement/ITS and the May outside-counsel proposal are facts only Chris has, so they go on the meeting list, not here."
s["agent"] = {"status": "waiting", "since": now, "handled": 2}
json.dump(s, open(f, "w", encoding="utf-8"), indent=2, ensure_ascii=False)
print("ok")

